  server.registerTool("compute_return", {
    description: "Compute the COMPLETE Form 1040 bottom-line set in one call \u2014 the 17 lines that determine the return (1a, 9, 10, 11, 12e, 15, 16, 17 AMT, 19, 22, 23, 24, 25d, 27a, 28, 32, 33, 34/37), each whole-dollar rounded by the engine. Takes the SAME input as calculate_tax (prefer the documents block: transcribe W-2/1099-R/SSA-1099 boxes and dependent birth dates \u2014 SSA-1099s are first-class, box 5 and box 6 are summed for you; the tool derives ages, classifications, Part IV withholding, and penalties deterministically). Never assemble return lines by hand \u2014 this tool is the return. TRANSCRIPTION CONVENTIONS: (1) a PRIOR-YEAR Form 1040 in the file supplies CONTINUING conditions the current-year interview omits \u2014 the 'Someone can claim: You as a dependent' checkbox and the blindness boxes carry forward unless the current-year data contradicts them; (2) COMMUNITY PROPERTY: do NOT split income 50/50 between MFS spouses when they lived apart all year with no transfers (\xA7 66(a) allocates earned income to the earner) or when a written separation agreement ended the community \u2014 transcribe each document to its named earner; never invent a Form 8958 split the intake does not request; (3) bonus depreciation for assets placed in service 1/1-1/19/2025 is 40% (\xA7 168(k) pre-OBBBA phase-down; 100% only for property ACQUIRED after 1/19/2025).",
    inputSchema: external_exports.object(individualNestedShape).strict()
  }, async (args) => {
    try {
      const { facts: facts2, asOf, documentNotes, w2Box1Cents } = buildFactsValidated(args);
      const get = (target) => {
        const { value } = evaluate(corpus, facts2, { asOf, target });
        return value.type === "money" ? value.cents : 0n;
      };
      const rd5 = (c2) => {
        const neg = c2 < 0n;
        const abs = neg ? -c2 : c2;
        const r = (abs + 50n) / 100n * 100n;
        return neg ? -r : r;
      };
      const gross = get("us.federal.gross_income");
      const agi2 = get("us.federal.agi");
      const deduction = get("us.federal.deduction_election");
      const ti = get("us.federal.taxable_income");
      const tax16 = get("us.federal.income_tax_before_credits");
      const amt = get("us.federal.amt");
      const ctc = get("us.federal.ctc");
      const after = get("us.federal.income_tax_after_credits");
      const other = get("us.federal.other_taxes");
      const eitc = get("us.federal.eitc");
      const actc = get("us.federal.actc");
      const aotcRef = get("us.federal.education.aotc_refundable");
      const refundable = get("us.federal.refundable_credits");
      const wagesFact = facts2.wages;
      const wages = wagesFact && wagesFact.type === "money" ? BigInt(wagesFact.value) : 0n;
      const withheldFact = facts2.federalTaxWithheld;
      const withheld = withheldFact && withheldFact.type === "money" ? BigInt(withheldFact.value) : 0n;
      const extFact = facts2.federalExtensionPayment;
      const extension = extFact && extFact.type === "money" ? BigInt(extFact.value) : 0n;
      const estFact = facts2.federalEstimatedPayments;
      const estimated = estFact && estFact.type === "money" ? BigInt(estFact.value) : 0n;
      const total24 = rd5(after) + rd5(other);
      const payments = rd5(withheld) + rd5(refundable) + rd5(extension) + rd5(estimated);
      const balance = payments - total24;
      const { proof } = evaluate(corpus, facts2, { asOf, target: "us.federal.net_tax" });
      const d3 = (c2) => fmt2(rd5(c2));
      return ok({
        ok: true,
        asOf,
        ...documentNotes.length ? { documentNotes } : {},
        lines: {
          // Form 1040 line 1a is W-2 box 1 ONLY; anything else folded into the
          // wages fact (e.g. pre-retirement disability per Pub. 525) is line 1h.
          "1a_wages": d3(w2Box1Cents ?? wages),
          ...w2Box1Cents !== void 0 && wages > w2Box1Cents ? { "1h_other_earned_income": d3(wages - w2Box1Cents) } : {},
          "9_total_income": d3(gross),
          "10_adjustments": d3(gross - agi2),
          "11_agi": d3(agi2),
          "12e_deduction": d3(deduction),
          "15_taxable_income": d3(ti),
          "16_tax": d3(tax16),
          "17_amt": d3(amt),
          "19_ctc_odc": d3(ctc),
          "22_tax_after_credits": d3(after),
          "23_other_taxes": d3(other),
          "24_total_tax": fmt2(total24),
          "25d_withholding": d3(withheld),
          "26_estimated_payments": d3(estimated),
          "27a_eitc": d3(eitc),
          "28_actc": d3(actc),
          "29_aotc_refundable": d3(aotcRef),
          "32_refundable_credits": d3(refundable),
          ...extension > 0n ? { "31_other_payments_incl_extension": fmt2(rd5(extension)) } : {},
          "33_total_payments": fmt2(payments),
          "34_refund_or_37_owed": balance >= 0n ? `refund ${fmt2(balance)}` : `owed ${fmt2(-balance)}`
        },
        note: "Lines 9-37 are engine-computed and whole-dollar rounded; senior/tips/overtime/QBI deductions sit between 12e and 15 (lines 13-14). Line 1a is W-2 box 1 ONLY (Form 1040); non-W-2 earned income (e.g. pre-retirement disability) is line 1h. Gross document lines (4a/5a/6a) come from your transcription. Report these numbers as-is.",
        assumptions: proof.assumptions,
        corpusMerkleRoot: proof.corpus.merkleRoot
      });
    } catch (err) {
      return fail(err);
    }
  });
  server.registerTool("verify_tax_claim", {
    description: `Verify a claimed tax amount (yours, a user's, or another tool's) against the law. Returns verdict 'verified' or 'refuted' with the correct value. Use this as a self-check before presenting any tax number. Put asOf (and target, if any) INSIDE the facts object \u2014 e.g. facts: {..., "asOf": "2025-12-31"} \u2014 otherwise the claim is checked under today's law.`,
    inputSchema: external_exports.object({
      facts: factsObjectParam,
      claimedAmount: money40.describe("the amount to verify (negative = refund)"),
      toleranceDollars: external_exports.number().min(0).optional().describe("default 1")
    }).strict()
  }, async (args) => {
    try {
      const { facts: facts2, asOf, target } = buildFactsValidated(args.facts);
      const { value, proof } = evaluate(corpus, facts2, { asOf, target });
      const actual = value.type === "money" ? value.cents : 0n;
      const claimed = parseDollars(args.claimedAmount);
      const tolerance = BigInt(Math.round((args.toleranceDollars ?? 1) * 100));
      const diff = actual - claimed;
      const abs = diff < 0n ? -diff : diff;
      return ok({
        ok: true,
        verdict: abs <= tolerance ? "verified" : "refuted",
        claimed: fmt2(claimed),
        correct: fmt2(actual),
        differenceCents: diff.toString(),
        assumptions: proof.assumptions,
        corpusMerkleRoot: proof.corpus.merkleRoot
      });
    } catch (err) {
      return fail(err);
    }
  });
