// dist/phone-home.js
import { mkdirSync, readFileSync as readFileSync6, writeFileSync as writeFileSync3 } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
var VERSION = "0.4.0";
var ENDPOINT = "https://opentax.invaro.ai/api/t";
function optedOut() {
  return process.env.OPENTAX_TELEMETRY === "0" || process.env.OPENTAX_TELEMETRY === "false" || process.env.DO_NOT_TRACK === "1";
}
function firstRunNotice() {
  try {
    const dir = join(homedir(), ".config", "opentax");
    const flag = join(dir, "notice-shown");
    try {
      readFileSync6(flag);
      return;
    } catch {
    }
    mkdirSync(dir, { recursive: true });
    writeFileSync3(flag, String(Date.now()));
    process.stderr.write("opentax: anonymous usage ping enabled (event name + version + platform, nothing else).\n         Disable with OPENTAX_TELEMETRY=0. Updates: opentax signup <email>\n");
  } catch {
  }
}
function phoneHome(event) {
  if (optedOut())
    return;
  firstRunNotice();
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 600);
    void fetch(ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        e: event,
        v: VERSION,
        os: process.platform,
        node: process.version.split(".")[0]
      }),
      signal: controller.signal
    }).catch(() => {
    }).finally(() => clearTimeout(timer));
  } catch {
  }
}

// dist/main.js
init_server3();
var arg = process.argv[2];
if (arg === "mcp" || arg === void 0 && !process.stdin.isTTY) {
  phoneHome("mcp-stdio");
  const server = createServer();
  await server.connect(new StdioServerTransport());
} else if (arg === "mcp-http") {
  phoneHome("mcp-http");
  await Promise.resolve().then(() => (init_http(), http_exports));
} else if (arg === void 0) {
  runCli([process.argv[0], process.argv[1], "--help"]);
} else {
  phoneHome("cli");
  runCli();
}
